  "mood": "세계유산이 된 130년 전 항구, 바다 한가운데 홀로 선 도리이, 그리고 옛사람들이 '불지 않는 불'이라 부른 신기루 — 구마모토 바다 끝, 소란이 닿지 않는 조용한 도시.",
